//! Finite-shot phase calibration: independent noisy residual and parameter-shift probes.
//! Every attempted photon, including detector misses, is charged to the shot budget.
use burn::tensor::{DType, Device, Tensor, TensorData};
use burn_quantum::photonic::{optics::*, runtime::shot_seed};
use burn_quantum_example::{ExampleResult, values};
use rand::{Rng, SeedableRng};
use rand_chacha::ChaCha8Rng;
use serde_json::{json, Value};
const SHOTS: usize = 512;
const STEPS: usize = 80;
const TRAIN: usize = 8;
const TRUE_OFFSET: f64 = 0.65;
const EFFICIENCY: f64 = 0.8;
fn analytic(x: f64, offset: f64) -> f64 {
    EFFICIENCY * ((x + offset) / 2.).cos().powi(2)
}
fn experiment(batch: usize, device: &Device) -> ExampleResult<SinglePhotonPhaseExperiment> {
    let limits = Default::default();
    let bs = Interferometer::beam_splitter(2, ModeId(0), ModeId(1), std::f64::consts::FRAC_PI_2)?;
    let input = FockState::number(
        FockBasis::new(2, PhotonSector::UpTo(1), 3)?,
        &[1, 0],
        batch,
        device,
        DType::F32,
        limits,
    )?
    .apply(&bs, limits)?;
    Ok(SinglePhotonPhaseExperiment::new(
        input,
        ModeId(0),
        bs.adjoint(),
        vec![Detector::threshold(EFFICIENCY, 0.)?; 2],
        4,
        limits,
    )?)
}
fn angles(points: &[f64], offset: f64, device: &Device) -> Tensor<1> {
    Tensor::from_data(
        TensorData::new(
            points.iter().map(|&x| (x + offset) as f32).collect(),
            [points.len()],
        ),
        device,
    )
}

fn categorical_trace(probabilities: &[f64], seed: u64, row: usize) -> (Vec<usize>, Vec<f64>, Vec<f64>) {
    let mut total=0.;
    let cdf: Vec<_>=probabilities.iter().map(|p| {total+=p.max(0.);total}).collect();
    let mut rng=ChaCha8Rng::seed_from_u64(shot_seed(seed,row as u64,0x0052_4541_444f_5554));
    let draws:Vec<f64>=(0..SHOTS).map(|_|rng.random::<f64>()).collect();
    let selected=draws.iter().map(|u|cdf.partition_point(|p|*p<=u*total).min(cdf.len()-1)).collect();
    (selected,draws,cdf.iter().map(|p|p/total).collect())
}
fn main() -> ExampleResult<()> {
    let cpu=Device::flex();
    let (gpu,setup)=Device::wgpu_options().device_kind(burn::tensor::DeviceKind::DiscreteGpu(0)).init_with_setup()?;
    assert_eq!(setup.adapter.get_info().device_type,burn::tensor::wgpu::wgpu::DeviceType::DiscreteGpu);
    let devices=[cpu,gpu];
    let experiments=[experiment(TRAIN,&devices[0])?,experiment(TRAIN,&devices[1])?];
    let training:Vec<_>=(0..TRAIN).map(|i|-1.5+3.*i as f64/(TRAIN-1) as f64).collect();
    let testing:Vec<_>=(0..17).map(|i|-1.5+3.*(i as f64+0.5)/17.).collect();
    let mut runs=Vec::new();
    let mut max_analytic_error=[0f64;2];
    let mut max_identical_angle_probability_gap=0f64;
    let mut first_crossing:Option<Value>=None;
    for (seed,initial) in [(7,-0.4),(11,0.1),(19,1.2)] {
        let mut offsets=[initial;2];
        let mut history=Vec::new();
        for step in 0..STEPS {
            let before=offsets;
            let residual_seed=shot_seed(seed,step as u64,1);
            let derivative_seed=shot_seed(seed,step as u64,2);
            let probe_seeds=[residual_seed,shot_seed(derivative_seed,0,0x504c_5553),shot_seed(derivative_seed,0,0x004d_494e_5553)];
            let shifts=[0.,std::f64::consts::FRAC_PI_2,-std::f64::consts::FRAC_PI_2];
            let mut all_probabilities=vec![Vec::new(),Vec::new()];
            let mut all_counts=vec![Vec::new(),Vec::new()];
            let mut gradients=[0.;2];
            for backend in 0..2 {
                let mut means=Vec::new();
                for probe in 0..3 {
                    let angle=if probe==0 { angles(&training,offsets[backend],&devices[backend]) }
                        else { angles(&training,offsets[backend],&devices[backend])+shifts[probe] };
                    let actual_angles=values(angle.clone())?;
                    let distribution=experiments[backend].evaluate(angle)?;
                    let probabilities=values(distribution.probabilities())?;
                    let records=distribution.records();
                    let index=records.iter().position(|r|r==&[1,0]).unwrap();
                    let counts=distribution.sample_counts(SHOTS,probe_seeds[probe],TRAIN*SHOTS)?;
                    for (row,(&angle,ps)) in actual_angles.iter().zip(probabilities.chunks_exact(records.len())).enumerate() {
                        for (record,&probability) in records.iter().zip(ps) {
                            let expected=match record.as_slice(){[0,0]=>1.-EFFICIENCY,[0,1]=>EFFICIENCY*(angle/2.).sin().powi(2),[1,0]=>EFFICIENCY*(angle/2.).cos().powi(2),[1,1]=>0.,_=>panic!()};
                            max_analytic_error[backend]=max_analytic_error[backend].max((probability-expected).abs());
                        }
                        let (samples,_,_)=categorical_trace(ps,probe_seeds[probe],row);
                        let mut reconstructed=vec![0;records.len()];
                        for sample in samples { reconstructed[sample]+=1; }
                        assert_eq!(reconstructed,counts[row].counts,"sampling diagnostic must exactly reconstruct production RNG/CDF");
                    }
                    means.push(counts.iter().map(|h|h.counts[index] as f64/SHOTS as f64).collect::<Vec<_>>());
                    all_probabilities[backend].push(probabilities);
                    all_counts[backend].push(counts.iter().map(|h|h.counts.clone()).collect::<Vec<_>>());
                }
                gradients[backend]=(0..TRAIN).map(|row|2.*(means[0][row]-analytic(training[row],TRUE_OFFSET))*(means[1][row]-means[2][row])/2.).sum::<f64>()/TRAIN as f64;
                offsets[backend]-=1.2*gradients[backend];
            }
            let same_angles=before[0]==before[1];
            if same_angles {
                for probe in 0..3 {
                    for (&a,&b) in all_probabilities[0][probe].iter().zip(&all_probabilities[1][probe]) {
                        max_identical_angle_probability_gap=max_identical_angle_probability_gap.max((a-b).abs());
                    }
                }
            }
            if first_crossing.is_none() && all_counts[0]!=all_counts[1] {
                let mut crossings=Vec::new();
                for probe in 0..3 {for row in 0..TRAIN {
                    let a=&all_probabilities[0][probe][row*4..row*4+4];
                    let b=&all_probabilities[1][probe][row*4..row*4+4];
                    let (samples_a,draws,thresholds_a)=categorical_trace(a,probe_seeds[probe],row);
                    let (samples_b,_,thresholds_b)=categorical_trace(b,probe_seeds[probe],row);
                    for (shot,(&ca,&cb)) in samples_a.iter().zip(&samples_b).enumerate() {
                        if ca!=cb {crossings.push(json!({"probe":probe,"row":row,"shot":shot,"input_phase":training[row],"uniform_draw":draws[shot],"cpu_record_index":ca,"wgpu_record_index":cb,"cpu_probabilities":a,"wgpu_probabilities":b,"cpu_normalized_cdf":thresholds_a,"wgpu_normalized_cdf":thresholds_b,"probe_seed":probe_seeds[probe]}));}
                    }
                }}
                first_crossing=Some(json!({"seed":seed,"step":step,"offsets_before":before,"offsets_after":offsets,"same_parameter_inputs":same_angles,"gradients":gradients,"crossings":crossings}));
                eprintln!("first crossing {}",first_crossing.as_ref().unwrap());
            }
            history.push(json!({"step":step,"offsets_before":before,"gradients":gradients,"offsets_after":offsets,"different_count_rows":(0..3).map(|probe|(0..TRAIN).filter(|&row|all_counts[0][probe][row]!=all_counts[1][probe][row]).count()).sum::<usize>()}));
        }
        let mut mses=Vec::new();
        for backend in 0..2 {
            let prediction=experiment(testing.len(),&devices[backend])?.evaluate(angles(&testing,offsets[backend],&devices[backend]))?;
            let index=prediction.records().iter().position(|r|r==&[1,0]).unwrap();
            let probabilities=values(prediction.probabilities().slice_dim(1,index..index+1))?;
            mses.push(probabilities.iter().zip(&testing).map(|(&p,&x)|(p-analytic(x,TRUE_OFFSET)).powi(2)).sum::<f64>()/testing.len() as f64);
        }
        runs.push(json!({"seed":seed,"final_offsets":offsets,"offset_errors":offsets.map(|x|(x-TRUE_OFFSET).abs()),"test_mses":mses,"history":history}));
        eprintln!("seed {seed} offsets {offsets:?}");
    }
    println!("{}",serde_json::to_string_pretty(&json!({"adapter":setup.adapter.get_info().name,"device_order":["cpu","wgpu"],"max_probability_analytic_error":max_analytic_error,"max_identical_angle_probability_gap":max_identical_angle_probability_gap,"first_crossing":first_crossing,"runs":runs}))?);
    Ok(())
}
